CREATE OR REPLACE FUNCTION public.register_moot_court(_full_name text, _email text, _phone text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE new_id uuid; BEGIN INSERT INTO public.moot_court_registrations (full_name, email, phone) VALUES (_full_name, lower(trim(_email)), _phone) RETURNING id INTO new_id; RETURN new_id; END; $$; GRANT EXECUTE ON FUNCTION public.register_moot_court(text, text, text) TO anon, authenticated, service_role;